style.css:
@-moz-document domain("youtube.com") {
body {
    background-image: url("https://i.pinimg.com/736x/45/e8/8e/45e88efcefb8e9930e5c97e02af77588.jpg") !important;
    background-size: cover !important;
    background-repeat: no-repeat !important;
    background-attachment: fixed !important;
    background-position: center center !important;
    color: white !important;
    font-family: "Old English Text MT", "Blackletter", serif !important;
  }

  #page-manager, #content, ytd-app {
    background-color: rgba(0, 0, 0, 0.85) !important;
  }

  h1, h2, h3, h4, yt-formatted-string, ytd-video-renderer, ytd-rich-item-renderer {
    color: white !important;
    font-family: "Old English Text MT", "Blackletter", serif !important;
    text-shadow: 1px 1px 2px black;
  }

  a, ytd-button-renderer, .yt-simple-endpoint {
    color: #ccc !important;
  }

  paper-progress, tp-yt-paper-progress {
    background: transparent !important;
  }

  #logo-icon, .ytd-topbar-logo-renderer {
    filter: grayscale(100%) brightness(0.7);
  }

  ::-webkit-scrollbar {
    width: 10px;
  }
  ::-webkit-scrollbar-track {
    background: #111;
  }
  ::-webkit-scrollbar-thumb {
    background: #444;
  }

  #movie_player {
    background-color: #000 !important;
  }
}
